contracts/RegistroVeicular.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

import "@openzeppelin/contracts-upgradeable/access/AccessControlUpgradeable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/Initializable.sol";
import "@openzeppelin/contracts-upgradeable/proxy/utils/UUPSUpgradeable.sol";

contract RegistroVeicular is Initializable, AccessControlUpgradeable, UUPSUpgradeable {

    // --- Papéis de Controle de Acesso ---
    bytes32 public constant DMV_ROLE          = keccak256("DMV_ROLE");
    bytes32 public constant MECHANIC_ROLE     = keccak256("MECHANIC_ROLE");
    bytes32 public constant INSURER_ROLE      = keccak256("INSURER_ROLE");
    bytes32 public constant MANUFACTURER_ROLE = keccak256("MANUFACTURER_ROLE");
    bytes32 public constant DEALER_ROLE       = keccak256("DEALER_ROLE");

    // --- Enums ---
    enum PapelAtor     { MONTADORA, AUTORIDADE, OFICINA, SEGURADORA, CONCESSIONARIA }
    enum EstiloVeiculo { DESCONHECIDO, SEDAN, SUV, HATCHBACK, PICAPE, COUPE, VAN, MOTOCICLETA }
    enum TipoUso       { DESCONHECIDO, PESSOAL, COMERCIAL, FROTA, ALUGUEL }
    enum GravidadeImpacto { DESCONHECIDA, BAIXA, MEDIA, ALTA, PERDA_TOTAL }
    enum TipoTitulo    { DESCONHECIDO, LIMPO, LEILAO, RECONSTRUIDO, INUNDACAO, QUEIMADO }
    enum TipoServico   { PREVENTIVA, CORRETIVA, SINISTRO, REVISAO, RECALL, OUTROS }

    // --- Structs (empacotados para minimizar slots de storage) ---

    struct Ator {
        string nome;
        PapelAtor papel;
        bool ativo;
    }

    // slot 1: address(20) + uint16(2) + EstiloVeiculo(1) = 23 bytes
    // slot 2: string modelo (dinâmico)
    struct Modelo {
        address assinatura_marca;
        uint16  ano;
        EstiloVeiculo estilo;
        string  modelo;
    }

    // slot 1: address(20) + uint48(6) = 26 bytes
    // slot 2: uint(32)
    // slot 3: string cor (dinâmico)
    struct Veiculo {
        address assinatura_montadora;
        uint48  data_fabricacao;
        uint    id_modelo;
        string  cor;
    }

    // slot 1: address(20) + uint48(6) + TipoUso(1) + uint32(4) = 31 bytes
    // slot 2: address(20)
    struct RegistroDono {
        address dono;
        uint48  data_comeco;
        TipoUso tipo_uso;
        uint32  localidade_id;
        address assinatura_reportador;
    }

    // slot 1: address(20) + uint48(6) + GravidadeImpacto(1) + bool(1) + bool(1) = 29 bytes
    // slot 2: string local (dinâmico)
    struct RegistroAcidente {
        address assinatura_reportador;
        uint48  data;
        GravidadeImpacto gravidade;
        bool    airbags_acionados;
        bool    dano_estrutural;
        string  local;
    }

    // slot 1: address(20) + uint48(6) + TipoTitulo(1) = 27 bytes
    // slot 2: string detalhes (dinâmico)
    struct RegistroTitulo {
        address assinatura_reportador;
        uint48  data;
        TipoTitulo tipo_titulo;
        string  detalhes;
    }

    // slot 1: address(20) + uint48(6) + uint32(4) = 30 bytes  ← tudo em 1 slot!
    struct RegistroOdometro {
        address assinatura_reportador;
        uint48  data;
        uint32  quilometragem;
    }

    // slot 1: address(20) + uint48(6) + TipoServico(1) = 27 bytes
    // slot 2: string descricao (dinâmico)
    struct RegistroServico {
        address assinatura_oficina;
        uint48  data;
        TipoServico tipo;
        string  descricao;
    }

    // slot 1: address(20) + uint48(6) + bool(1) = 27 bytes
    // slot 2: string recall_id (dinâmico)
    // slot 3: string descricao (dinâmico)
    struct RegistroRecall {
        address assinatura_montadora;
        uint48  data;
        bool    resolvido;
        string  recall_id;
        string  descricao;
    }

    // slot 1: address(20)
    // slot 2: string cor (dinâmico)
    // slot 3: string placa (dinâmico)
    struct RegistroIdentificacao {
        address assinatura_reportador;
        string  cor;
        string  placa;
    }

    // --- Storage ---

    mapping(address => Ator) public atores;
    address[] public enderecosAtores;
    mapping(address => uint) private _atorIndex; // índice em enderecosAtores para swap-and-pop

    mapping(uint => Modelo) public modelos;
    uint public proximoIdModelo;

    // Chaves internas usam bytes32 = keccak256(chassi) para economizar gas
    mapping(bytes32 => Veiculo)            private _veiculos;
    mapping(bytes32 => RegistroDono[])     private _historicoDonos;
    mapping(bytes32 => RegistroAcidente[]) private _historicoAcidentes;
    mapping(bytes32 => RegistroTitulo[])   private _historicoTitulos;
    mapping(bytes32 => RegistroOdometro[]) private _odometro;
    mapping(bytes32 => RegistroServico[])  private _historicoServicos;
    mapping(bytes32 => RegistroRecall[])   private _historicoRecall;
    mapping(bytes32 => RegistroIdentificacao[]) private _historicoIdentificacao;

    // --- Eventos ---
    event ModeloAdicionado(uint indexed id_modelo, string modelo, uint16 ano, address indexed assinatura_marca);
    event VeiculoAdicionado(string chassi, uint indexed id_modelo, address indexed assinatura_montadora);
    event RegistroDonoAdicionado(string chassi, address indexed novo_dono, uint data_comeco, address indexed assinatura_reportador);
    event RegistroAcidenteAdicionado(string chassi, uint data, GravidadeImpacto gravidade, address indexed assinatura_reportador);
    event RegistroTituloAdicionado(string chassi, uint data, TipoTitulo tipo_titulo, address indexed assinatura_reportador);
    event RegistroOdometroAdicionado(string chassi, uint data, uint32 quilometragem, address indexed assinatura_reportador);
    event RegistroServicoAdicionado(string chassi, uint data, TipoServico tipo, address indexed assinatura_oficina);
    event RegistroRecallAdicionado(string chassi, string recall_id, bool resolvido, address indexed assinatura_montadora);
    event AtorRegistrado(address indexed conta, string nome, PapelAtor papel);
    event AtorRevogado(address indexed conta);
    event RegistroIdentificacaoAdicionado(string indexed chassi, string placa, string cor, address indexed assinatura_reportador);

    // --- UUPS: bloqueia inicialização direta na implementação ---
    /// @custom:oz-upgrades-unsafe-allow constructor
    constructor() { _disableInitializers(); }

    function initialize(address _admin) external initializer {
        __AccessControl_init();
        _grantRole(DEFAULT_ADMIN_ROLE, _admin);
        atores[_admin] = Ator("Sistema Admin", PapelAtor.AUTORIDADE, true);
        enderecosAtores.push(_admin);
        _atorIndex[_admin] = 0;
    }

    // Apenas admin pode autorizar upgrade da implementação
    function _authorizeUpgrade(address) internal override onlyRole(DEFAULT_ADMIN_ROLE) {}

    // --- Helpers internos ---

    function _chassiKey(string calldata chassi) internal pure returns (bytes32) {
        return keccak256(abi.encodePacked(chassi));
    }

    function _veiculoExiste(bytes32 key) internal view returns (bool) {
        return _veiculos[key].assinatura_montadora != address(0);
    }

    // --- Modifier: roles permitidas para odômetro ---
    modifier onlyOdometroRole() {
        require(
            hasRole(DMV_ROLE, msg.sender) ||
            hasRole(MANUFACTURER_ROLE, msg.sender) ||
            hasRole(MECHANIC_ROLE, msg.sender),
            "RegistroVeicular: Acesso negado"
        );
        _;
    }

    // --- Governança (Apenas Admin) ---

    function registrarAtor(address _conta, string calldata _nome, PapelAtor _papel) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(bytes(_nome).length > 0, "RegistroVeicular: Nome obrigatorio");

        bool isNew = bytes(atores[_conta].nome).length == 0;

        if (isNew) {
            _atorIndex[_conta] = enderecosAtores.length;
            enderecosAtores.push(_conta);
        }

        atores[_conta] = Ator(_nome, _papel, true);

        if (_papel == PapelAtor.MONTADORA)       _grantRole(MANUFACTURER_ROLE, _conta);
        else if (_papel == PapelAtor.AUTORIDADE)  _grantRole(DMV_ROLE, _conta);
        else if (_papel == PapelAtor.OFICINA)     _grantRole(MECHANIC_ROLE, _conta);
        else if (_papel == PapelAtor.SEGURADORA)  _grantRole(INSURER_ROLE, _conta);
        else if (_papel == PapelAtor.CONCESSIONARIA) _grantRole(DEALER_ROLE, _conta);

        emit AtorRegistrado(_conta, _nome, _papel);
    }

    function revogarAtor(address _conta) external onlyRole(DEFAULT_ADMIN_ROLE) {
        require(atores[_conta].ativo, "RegistroVeicular: Ator nao esta ativo ou nao existe");

        atores[_conta].ativo = false;

        _revokeRole(MANUFACTURER_ROLE, _conta);
        _revokeRole(DMV_ROLE, _conta);
        _revokeRole(MECHANIC_ROLE, _conta);
        _revokeRole(INSURER_ROLE, _conta);
        _revokeRole(DEALER_ROLE, _conta);

        // Swap-and-pop: remove do array sem deixar buracos
        uint idx = _atorIndex[_conta];
        uint last = enderecosAtores.length - 1;
        if (idx != last) {
            address lastAddr = enderecosAtores[last];
            enderecosAtores[idx] = lastAddr;
            _atorIndex[lastAddr] = idx;
        }
        enderecosAtores.pop();
        delete _atorIndex[_conta];

        emit AtorRevogado(_conta);
    }

    function getTodosAtores() external view returns (address[] memory, Ator[] memory) {
        uint total = enderecosAtores.length;
        Ator[] memory lista = new Ator[](total);
        for (uint i = 0; i < total; i++) {
            lista[i] = atores[enderecosAtores[i]];
        }
        return (enderecosAtores, lista);
    }

    // --- Funções de Escrita ---

    function addModelo(string calldata _modelo, uint16 _ano, EstiloVeiculo _estilo) external onlyRole(MANUFACTURER_ROLE) {
        uint id = proximoIdModelo;
        modelos[id] = Modelo({
            assinatura_marca: msg.sender,
            ano:              _ano,
            estilo:           _estilo,
            modelo:           _modelo
        });
        proximoIdModelo++;
        emit ModeloAdicionado(id, _modelo, _ano, msg.sender);
    }

    function addVeiculo(string calldata _chassi, uint _id_modelo, uint48 _data_fabricacao, string calldata _cor) external onlyRole(MANUFACTURER_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(!_veiculoExiste(key), "RegistroVeicular: Chassi ja registrado");
        require(modelos[_id_modelo].assinatura_marca != address(0), "RegistroVeicular: Modelo nao encontrado");
        require(modelos[_id_modelo].assinatura_marca == msg.sender, "RegistroVeicular: Apenas a montadora do modelo pode registrar o veiculo");

        _veiculos[key] = Veiculo({
            assinatura_montadora: msg.sender,
            data_fabricacao:      _data_fabricacao,
            id_modelo:            _id_modelo,
            cor:                  _cor
        });
        emit VeiculoAdicionado(_chassi, _id_modelo, msg.sender);
    }

    function addRegistroDono(
        string calldata _chassi,
        address _novo_dono,
        uint48 _data_registro,
        uint32 _localidade_id,
        TipoUso _tipo_uso
    ) external onlyRole(DMV_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        _historicoDonos[key].push(RegistroDono({
            dono:                  _novo_dono,
            data_comeco:           _data_registro,
            tipo_uso:              _tipo_uso,
            localidade_id:         _localidade_id,
            assinatura_reportador: msg.sender
        }));
        emit RegistroDonoAdicionado(_chassi, _novo_dono, _data_registro, msg.sender);
    }

    function addRegistroAcidente(
        string calldata _chassi,
        uint48 _data,
        string calldata _local,
        GravidadeImpacto _gravidade,
        bool _airbags_acionados,
        bool _dano_estrutural
    ) external onlyRole(DMV_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        _historicoAcidentes[key].push(RegistroAcidente({
            assinatura_reportador: msg.sender,
            data:                  _data,
            gravidade:             _gravidade,
            airbags_acionados:     _airbags_acionados,
            dano_estrutural:       _dano_estrutural,
            local:                 _local
        }));
        emit RegistroAcidenteAdicionado(_chassi, _data, _gravidade, msg.sender);
    }

    function addRegistroTitulo(
        string calldata _chassi,
        uint48 _data,
        TipoTitulo _tipo_titulo,
        string calldata _detalhes
    ) external onlyRole(DMV_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        _historicoTitulos[key].push(RegistroTitulo({
            assinatura_reportador: msg.sender,
            data:                  _data,
            tipo_titulo:           _tipo_titulo,
            detalhes:              _detalhes
        }));
        emit RegistroTituloAdicionado(_chassi, _data, _tipo_titulo, msg.sender);
    }

    function addRegistroOdometro(
        string calldata _chassi,
        uint48 _data,
        uint32 _quilometragem
    ) external onlyOdometroRole {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        RegistroOdometro[] storage hist = _odometro[key];
        if (hist.length > 0) {
            require(
                _quilometragem > hist[hist.length - 1].quilometragem,
                "RegistroVeicular: A nova quilometragem deve ser maior que a anterior."
            );
        }

        hist.push(RegistroOdometro({
            assinatura_reportador: msg.sender,
            data:                  _data,
            quilometragem:         _quilometragem
        }));
        emit RegistroOdometroAdicionado(_chassi, _data, _quilometragem, msg.sender);
    }

    function addRegistroServico(
        string calldata _chassi,
        uint48 _data,
        string calldata _descricao,
        TipoServico _tipo
    ) external onlyRole(MECHANIC_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        _historicoServicos[key].push(RegistroServico({
            assinatura_oficina: msg.sender,
            data:               _data,
            tipo:               _tipo,
            descricao:          _descricao
        }));
        emit RegistroServicoAdicionado(_chassi, _data, _tipo, msg.sender);
    }

    function addRegistroRecall(
        string calldata _chassi,
        uint48 _data,
        string calldata _recall_id,
        string calldata _descricao,
        bool _resolvido
    ) external onlyRole(MANUFACTURER_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        _historicoRecall[key].push(RegistroRecall({
            assinatura_montadora: msg.sender,
            data:                 _data,
            resolvido:            _resolvido,
            recall_id:            _recall_id,
            descricao:            _descricao
        }));
        emit RegistroRecallAdicionado(_chassi, _recall_id, _resolvido, msg.sender);
    }

    function addRegistroIdentificacao(
        string calldata _chassi,
        string calldata _cor,
        string calldata _placa
    ) external onlyRole(DMV_ROLE) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");

        _historicoIdentificacao[key].push(RegistroIdentificacao({
            assinatura_reportador: msg.sender,
            cor:                   _cor,
            placa:                 _placa
        }));
        emit RegistroIdentificacaoAdicionado(_chassi, _placa, _cor, msg.sender);
    }

    // --- Funções de Leitura ---

    function getVeiculo(string calldata _chassi) external view returns (Veiculo memory) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _veiculos[key];
    }

    function getOdometro(string calldata _chassi) external view returns (RegistroOdometro memory) {
        bytes32 key = _chassiKey(_chassi);
        RegistroOdometro[] storage hist = _odometro[key];
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        require(hist.length > 0, "RegistroVeicular: Nenhum registro de odometro encontrado");
        return hist[hist.length - 1];
    }

    function getDonoAtual(string calldata _chassi) external view returns (RegistroDono memory) {
        bytes32 key = _chassiKey(_chassi);
        RegistroDono[] storage hist = _historicoDonos[key];
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        require(hist.length > 0, "RegistroVeicular: Nenhum registro de dono encontrado");
        return hist[hist.length - 1];
    }

    function getTituloAtual(string calldata _chassi) external view returns (RegistroTitulo memory) {
        bytes32 key = _chassiKey(_chassi);
        RegistroTitulo[] storage hist = _historicoTitulos[key];
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        require(hist.length > 0, "RegistroVeicular: Nenhum registro de titulo encontrado");
        return hist[hist.length - 1];
    }

    function getIdentificacao(string calldata _chassi) external view returns (RegistroIdentificacao memory) {
        bytes32 key = _chassiKey(_chassi);
        RegistroIdentificacao[] storage hist = _historicoIdentificacao[key];
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        require(hist.length > 0, "RegistroVeicular: Nenhum registro de identificacao encontrado");
        return hist[hist.length - 1];
    }

    function getHistoricoDonos(string calldata _chassi) external view returns (RegistroDono[] memory) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _historicoDonos[key];
    }

    function getHistoricoAcidentes(string calldata _chassi) external view returns (RegistroAcidente[] memory) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _historicoAcidentes[key];
    }

    function getHistoricoServicos(string calldata _chassi) external view returns (RegistroServico[] memory) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _historicoServicos[key];
    }

    function getHistoricoRecall(string calldata _chassi) external view returns (RegistroRecall[] memory) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _historicoRecall[key];
    }

    function getHistoricoOdometro(string calldata _chassi) external view returns (RegistroOdometro[] memory) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _odometro[key];
    }

    // --- Getters Paginados (offset + limit) ---

    function getHistoricoDonosPaginado(
        string calldata _chassi, uint offset, uint limit
    ) external view returns (RegistroDono[] memory, uint total) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        return _paginate(_historicoDonos[key], offset, limit);
    }

    function getHistoricoAcidentesPaginado(
        string calldata _chassi, uint offset, uint limit
    ) external view returns (RegistroAcidente[] memory, uint total) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        RegistroAcidente[] storage src = _historicoAcidentes[key];
        total = src.length;
        if (offset >= total || limit == 0) return (new RegistroAcidente[](0), total);
        uint end = _min(offset + limit, total);
        RegistroAcidente[] memory page = new RegistroAcidente[](end - offset);
        for (uint i = offset; i < end; i++) page[i - offset] = src[i];
        return (page, total);
    }

    function getHistoricoServicosPaginado(
        string calldata _chassi, uint offset, uint limit
    ) external view returns (RegistroServico[] memory, uint total) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        RegistroServico[] storage src = _historicoServicos[key];
        total = src.length;
        if (offset >= total || limit == 0) return (new RegistroServico[](0), total);
        uint end = _min(offset + limit, total);
        RegistroServico[] memory page = new RegistroServico[](end - offset);
        for (uint i = offset; i < end; i++) page[i - offset] = src[i];
        return (page, total);
    }

    function getHistoricoOdometroPaginado(
        string calldata _chassi, uint offset, uint limit
    ) external view returns (RegistroOdometro[] memory, uint total) {
        bytes32 key = _chassiKey(_chassi);
        require(_veiculoExiste(key), "RegistroVeicular: Chassi nao encontrado");
        RegistroOdometro[] storage src = _odometro[key];
        total = src.length;
        if (offset >= total || limit == 0) return (new RegistroOdometro[](0), total);
        uint end = _min(offset + limit, total);
        RegistroOdometro[] memory page = new RegistroOdometro[](end - offset);
        for (uint i = offset; i < end; i++) page[i - offset] = src[i];
        return (page, total);
    }

    function getModelosPorMontadora(address _montadora) external view returns (Modelo[] memory) {
        uint count = 0;
        for (uint i = 0; i < proximoIdModelo; i++) {
            if (modelos[i].assinatura_marca == _montadora) count++;
        }
        Modelo[] memory resultado = new Modelo[](count);
        uint idx = 0;
        for (uint i = 0; i < proximoIdModelo; i++) {
            if (modelos[i].assinatura_marca == _montadora) resultado[idx++] = modelos[i];
        }
        return resultado;
    }

    // --- Utils internos ---

    function _min(uint a, uint b) internal pure returns (uint) {
        return a < b ? a : b;
    }

    function _paginate(
        RegistroDono[] storage src,
        uint offset,
        uint limit
    ) internal view returns (RegistroDono[] memory page, uint total) {
        total = src.length;
        if (offset >= total || limit == 0) return (new RegistroDono[](0), total);
        uint end = _min(offset + limit, total);
        page = new RegistroDono[](end - offset);
        for (uint i = offset; i < end; i++) page[i - offset] = src[i];
    }
